#include "Monstey_NavSeamGeometry.hpp"
#include "Monstey_Core.hpp"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <random>
using namespace Monstey;
namespace {
using V=Monstey_NavSeamVector4;using Q=Monstey_NavSeamSegments;using J=Monstey_Json;
std::array<double,5> ClosestReference(const Q&q){std::array<double,4>a{},b{},d{};for(unsigned i=0;i<4;++i){a[i]=q[1][i]-static_cast<double>(q[0][i]);b[i]=q[3][i]-static_cast<double>(q[2][i]);d[i]=q[2][i]-static_cast<double>(q[0][i]);}auto dot=[](const auto&x,const auto&y){return x[0]*y[0]+x[1]*y[1]+x[2]*y[2];};const double aa=dot(a,a),bb=dot(b,b),ab=dot(a,b),ad=dot(a,d),bd=dot(b,d),denominator=aa*bb-ab*ab;double s=denominator!=0?(ad*bb-bd*ab)/denominator:0;s=std::clamp(s,0.0,1.0);double t=std::clamp(s*ab/bb-bd/bb,0.0,1.0);s=std::clamp((ab*t+ad)/aa,0.0,1.0);std::array<double,5>out{};for(unsigned i=0;i<4;++i)out[i]=q[0][i]+s*a[i]-q[2][i]-t*b[i];out[4]=out[0]*out[0]+out[1]*out[1]+out[2]*out[2];return out;}
}
int wmain(int argc,wchar_t**argv){try{Monstey_Require(argc==2,"Usage: NEW_REPORT");unsigned groups=0,cases=0;auto Distance=[&](const Q&q){const auto got=Monstey_NavSeamClosestSegments(q);const auto expected=ClosestReference(q);for(unsigned i=0;i<4;++i)Monstey_Require(std::abs(got.delta[i]-expected[i])<.0003*(1+std::abs(expected[i])),"Closest delta differs from independent segment reference");for(float v:got.squared_distance)Monstey_Require(std::abs(v-expected[4])<.0005*(1+expected[4]),"Closest squared distance differs from independent segment reference");++cases;return got;};Distance(Q{V{0,0,0,3},V{4,0,0,7},V{2,-1,0,9},V{2,3,0,13}});++groups;Distance(Q{V{0,0,0,3},V{4,0,0,7},V{2,-1,2,9},V{2,3,2,13}});++groups;Distance(Q{V{0,0,0,3},V{4,0,0,7},V{0,1,0,9},V{4,1,0,13}});++groups;Distance(Q{V{0,0,0,3},V{4,0,0,7},V{8,1,0,9},V{12,1,0,13}});++groups;std::mt19937 random(0xac1f80);std::uniform_real_distribution<float>v(-8,8);for(unsigned i=0;i<2048;++i){Q q{};for(auto&p:q)for(auto&lane:p)lane=v(random);Distance(q);}++groups;const V na{1,0,0,0},nb{-1,0,0,0},up{0,1,0,0};auto Overlap=[&](Q q,float minimum,int status,bool written){const auto got=Monstey_NavSeamProjectedOverlap(q,na,nb,up,minimum);Monstey_Require(got.status==status&&got.overlap_written==written,"Projection overlap status/write contract differs");for(const auto&p:got.projections)for(unsigned i=1;i<4;++i)Monstey_Require(p[i]==p[0],"XYZ dot projection was not replicated");++cases;return got;};Overlap(Q{V{0,0,0,3},V{4,0,0,7},V{3,0,0,9},V{1,0,0,13}},1,-1,true);++groups;Overlap(Q{V{0,0,0,3},V{4,0,0,7},V{3,0,0,9},V{6,0,0,13}},2,4,true);++groups;Overlap(Q{V{0,0,0,3},V{4,0,0,7},V{9,0,0,9},V{6,0,0,13}},2,3,false);++groups;Overlap(Q{V{0,0,0,3},V{0,0,0,7},V{3,0,0,9},V{6,0,0,13}},2,3,false);++groups;Overlap(Q{V{0,0,0,3},V{4,0,0,7},V{3,0,0,9},V{1,0,0,13}},3,-1,true);++groups;auto tilted=Monstey_NavSeamProjectedOverlap(Q{V{0,0,0,3},V{4,3,0,7},V{3,-2,0,9},V{1,2,0,13}},V{1,1,0,0},V{-1,1,0,0},up,1);Monstey_Require(tilted.status==-1&&tilted.overlap_written,"Up-axis component was not removed before projection");++cases;++groups;Monstey_WriteNewText(argv[1],J::object({{"status","PASS"},{"groups",groups},{"owned_geometry_cases",cases},{"randomized_closest_reference_cases",2048},{"native_program_called",false},{"process_accessed",false},{"scope","AC1F80/AC2340 closest-segment and AC1560 overlap owned arithmetic; full matcher still under reconstruction"}}).dump(2)+"\n");std::cout<<"PASS "<<groups<<" geometry groups, "<<cases<<" cases\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}